name: Rust checks

on:
  pull_request:
    paths:
      - exposed/**
      - Cargo.toml
      - Cargo.lock
      - clippy.toml
      - .sqlx/**
      - .github/workflows/rust.yml

permissions:
  contents: read

jobs:
  clippy:
    runs-on: ubuntu-24.04
    env:
      SQLX_OFFLINE: 'true'
      CARGO_PROFILE_DEV_DEBUG: '0'
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
      - name: Install Clippy
        run: |
          rustup toolchain install stable --profile minimal --component clippy
          rustup default stable
      # Clippy also sees event! expanded by ordinary info!, so check explicit
      # generic event macros in source while Clippy checks error!/warn! paths.
      - name: Check generic event macro ownership
        run: |
          if git grep -n -E '(tracing::event|log::log)[[:space:]]*!' -- exposed/src \
            ':!exposed/src/lib/inbound/http/tracing.rs' ':!exposed/src/bin/main.rs'; then
            echo 'Generic event macros belong to HTTP tracing or terminal server reporting.' >&2
            exit 1
          fi
      - name: Check Rust and error-emission ownership
        run: cargo clippy --locked --workspace --lib --bins -- -D warnings
disallowed-macros = [
    "tracing::error", "tracing::warn",
    "log::error", "log::warn",
]
use std::time::{Duration, Instant};

use axum::{
    Router,
    extract::{MatchedPath, Request},
    middleware::{self, Next},
    response::Response,
};
use tracing::{Instrument, Level};
use tracing_subscriber::EnvFilter;

use super::error::ResponseFailure;

pub(super) fn init_subscriber() -> anyhow::Result<()> {
    let directives = match std::env::var("RUST_LOG") {
        Ok(value) => value,
        Err(std::env::VarError::NotPresent) => "warn,exposed=info".into(),
        Err(error) => return Err(error.into()),
    };
    let filter = EnvFilter::builder().with_regex(false).parse(directives)?;
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .try_init()
        .map_err(|error| anyhow::anyhow!(error))
}

pub(super) fn instrument<S>(router: Router<S>) -> Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    router.layer(middleware::from_fn(trace_request))
}

async fn trace_request(request: Request, next: Next) -> Response {
    let method = request.method().clone();
    let route = request.extensions().get::<MatchedPath>().cloned();
    let health = route
        .as_ref()
        .is_some_and(|path| path.as_str() == "/healthz");
    let route_name = route.as_ref().map(MatchedPath::as_str);
    let span = if health {
        tracing::span!(Level::DEBUG, "http.request",
            http.request.method = %method, http.route = route_name)
    } else {
        tracing::span!(Level::INFO, "http.request",
            http.request.method = %method, http.route = route_name)
    };
    async move {
        let started = Instant::now();
        let response = next.run(request).await;
        complete(
            &response,
            started.elapsed(),
            &method,
            route.as_ref(),
            health,
        );
        response
    }
    .instrument(span)
    .await
}

fn complete(
    response: &Response,
    latency: Duration,
    method: &axum::http::Method,
    route: Option<&MatchedPath>,
    health: bool,
) {
    let status = response.status();
    let diagnostic = response
        .extensions()
        .get::<ResponseFailure>()
        .map(ResponseFailure::diagnostic);
    let category = response
        .extensions()
        .get::<ResponseFailure>()
        .map(ResponseFailure::category)
        .or_else(|| {
            if status.is_server_error() {
                Some("http.server_error")
            } else if status.is_client_error() {
                Some("http.client_error")
            } else {
                None
            }
        });
    let route = route.map(MatchedPath::as_str);
    macro_rules! emit {
        ($level:expr) => {
            tracing::event!(
                name: "http.request.completed",
                $level,
                name = "http.request.completed",
                http.request.method = %method,
                http.route = route,
                http.response.status_code = u64::from(status.as_u16()),
                duration_ms = latency.as_secs_f64() * 1000.0,
                error.type = category,
                error.message = diagnostic,
            )
        };
    }
    if status.is_server_error() {
        emit!(Level::ERROR);
    } else if status.is_client_error() {
        emit!(Level::WARN);
    } else if health {
        emit!(Level::DEBUG);
    } else {
        emit!(Level::INFO);
    }
}

